def sign(self, pkt, key):
        """
        Sign an IPsec (ESP or AH) packet with this algo.

        @param pkt:    a packet that contains a valid encrypted ESP or AH layer
        @param key:    the authentication key, a byte string

        @return: the signed packet
        """
        if not self.mac:
            return pkt

        mac = self.new_mac(key)

        if pkt.haslayer(ESP):
            mac.update(raw(pkt[ESP]))
            pkt[ESP].data += mac.finalize()[:self.icv_size]

        elif pkt.haslayer(AH):
            clone = zero_mutable_fields(pkt.copy(), sending=True)
            mac.update(raw(clone))
            pkt[AH].icv = mac.finalize()[:self.icv_size]

        return pkt

def get_sentence_xpath_tuples(filename_url_or_filelike,
                              xpath_to_text=TEXT_FINDER_XPATH):
    """
    Given a url and xpath, this function will download, parse, then
    iterate though queried text-nodes. From the resulting text-nodes,
    extract a list of (text, exact-xpath) tuples.
    """

    parsed_html = get_html_tree(filename_url_or_filelike)

    try:
        xpath_finder = parsed_html.getroot().getroottree().getpath
    except(AttributeError):
        xpath_finder = parsed_html.getroottree().getpath

    nodes_with_text = parsed_html.xpath(xpath_to_text)

    sent_xpath_pairs = [
        # hard-code paragraph breaks (there has to be a better way)
        ('\n\n' + s, xpath_finder(n)) if e == 0
        else (s, xpath_finder(n))
        for n in nodes_with_text
        for e, s in enumerate(SENTENCE_TOKEN_PATTERN.split(
            BRACKET_PATTERN.sub('', ''.join(n.xpath('.//text()')))))
        if s.endswith(tuple(SENTENCE_ENDING))
        ]

    return sent_xpath_pairs

def solve(m,c):
    """
    run the algorithm to find the path list
    """
    G={ (m,c,1):[] }
    frontier=[ (m,c,1) ]  # 1 as boat starts on left bank 
    while len(frontier) > 0:
        hold=list(frontier)
        for node in hold:
            newnode=[]
            frontier.remove(node)
            newnode.extend(pick_next_boat_trip(node, m,c, frontier))
            for neighbor in newnode:
                if neighbor not in G:
                    G[node].append(neighbor)
                    G[neighbor]=[node]
                    frontier.append(neighbor)
    return mod_plan.find_path_BFS(G,(m,c,1),(0,0,0))

