def visit_FunctionDeclaration(self, node):
        """Visitor for `FunctionDeclaration` AST node."""
        for parameter in node.parameters:
            try:
                var_name = parameter.variable.identifier.name
                var_is_mutable = parameter.variable.is_mutable
            except AttributeError:
                raise SementicError('Invalid parameter.')

            var_symbol = VariableSymbol(var_name, var_is_mutable)

            if self.table[var_name] is not None:
                raise SementicError(f"Duplicated `{var_name}` function parameter.")

            self.table[var_name] = var_symbol

        self.visit(node.body)

def _parsed_cmd(self):
        """
        We need to take into account two cases:

        - ['python code.py foo bar']: Used mainly with dvc as a library
        - ['echo', 'foo bar']: List of arguments received from the CLI

        The second case would need quoting, as it was passed through:
                dvc run echo "foo bar"
        """
        if len(self.args.command) < 2:
            return " ".join(self.args.command)

        return " ".join(self._quote_argument(arg) for arg in self.args.command)

def handle_url(url, session, res):
    """Parse one search result page."""
    print("Parsing", url, file=sys.stderr)
    try:
        data = getPageContent(url, session)
    except IOError as msg:
        print("ERROR:", msg, file=sys.stderr)
        return
    for match in url_matcher.finditer(data):
        url = match.group(1) + '/'
        name = unescape(match.group(2))
        name = asciify(name.replace('&', 'And').replace('@', 'At'))
        name = capfirst(name)
        if name in exclude_comics:
            continue
        if contains_case_insensitive(res, name):
            # we cannot handle two comics that only differ in case
            print("INFO: skipping possible duplicate", repr(name), file=sys.stderr)
            continue
        # find out how many images this comic has
        end = match.end()
        mo = num_matcher.search(data[end:])
        if not mo:
            print("ERROR:", repr(data[end:end+300]), file=sys.stderr)
            continue
        num = int(mo.group(1))
        url = url_overrides.get(name, url)
        try:
            if "/d/" not in url:
                check_robotstxt(url+"d/", session)
            else:
                check_robotstxt(url, session)
        except IOError:
            print("INFO: robots.txt denied for comicgenesis", repr(name))
            continue
        else:
            res[name] = (url, num)

def _get_updated_values(before_values, after_values):
    """ Get updated values from 2 dicts of values

    Args:
        before_values (dict): values before update
        after_values (dict): values after update

    Returns:
        dict: a diff dict with key is field key, value is tuple of
              (before_value, after_value)
    """
    assert before_values.keys() == after_values.keys()
    return dict([(k, [before_values[k], after_values[k]])
                 for k in before_values.keys()
                 if before_values[k] != after_values[k]])

def restoreValue(self, xelem):
        """
        Stores the value for the inptued instance to the given xml element.
        
        :param      xelem | <xml.etree.Element>
        
        :return     <variant>
        """
        typ = xelem.get('type')
        
        if typ == 'color':
            return QtGui.QColor(xelem.text)
        
        elif typ == 'point':
            return QtCore.QPoint(*map(int, xelem.text.split(',')))
        
        elif typ == 'pointf':
            return QtCore.QPointF(*map(float, xelem.text.split(',')))
        
        elif typ == 'rect':
            return QtCore.QRectF(*map(int, xelem.text.split(',')))
        
        elif typ == 'rectf':
            return QtCore.QRectF(*map(float, xelem.text.split(',')))
        
        elif typ == 'bytea':
            return QtCore.QByteArray(cPickle.loads(xelem.text))
        
        elif typ == 'pickle':
            return cPickle.loads(xelem.text)
        
        elif typ == 'xml':
            return xelem[0]
        
        elif typ in ('str', 'unicode'):
            return xelem.text
        
        else:
            try:
                return eval('{0}({1})'.format(typ, xelem.text))
            except:
                return None

